intfalsefileperms stringfilename
获取指定文件权限。

  &reftitle.examples;



    以八进制的形式显示文件的权限


<?php
echo substr(sprintf('%o', fileperms('/tmp')), -4);
echo substr(sprintf('%o', fileperms('/etc/passwd')), -4);
?>


    &example.outputs;


1777
0644




    输出全部权限


<?php
$perms = fileperms('/etc/passwd');

switch ($perms & 0xF000) {
    case 0x1000: $info = 'p'; break; // FIFO 管道
    case 0x2000: $info = 'c'; break; // 字符设备
    case 0x4000: $info = 'd'; break; // 目录
    case 0x6000: $info = 'b'; break; // 块设备
    case 0x8000: $info = '-'; break; // regular
    case 0xA000: $info = 'l'; break; // 符号链接
    case 0xC000: $info = 's'; break; // 套接字

    // 位置
    default: $info = 'u';
}

// 所有者
$setuid = $perms & 0x0800;
$info .= (($perms & 0x0100) ? 'r' : '-');
$info .= (($perms & 0x0080) ? 'w' : '-');
$info .= (($perms & 0x0040) ? ($setuid ? 's' : 'x') : ($setuid ? 'S' : '-'));

// 组
$setgid = $perms & 0x0400;
$info .= (($perms & 0x0020) ? 'r' : '-');
$info .= (($perms & 0x0010) ? 'w' : '-');
$info .= (($perms & 0x0008) ? ($setgid ? 's' : 'x') : ($setgid ? 'S' : '-'));

// 其它
$sticky = $perms & 0x0200;
$info .= (($perms & 0x0004) ? 'r' : '-');
$info .= (($perms & 0x0002) ? 'w' : '-');
$info .= (($perms & 0x0001) ? ($sticky ? 't' : 'x') : ($sticky ? 'T' : '-'));

echo $info;
?>


    &example.outputs;


